  function getMaxOrden($wf_flujo_id)
  {
    $conexion = Propel::getConnection();
    $consulta = "SELECT MAX(%s) AS max FROM %s where %s=".$wf_flujo_id."  ";
    $consulta = sprintf($consulta, WfActividadTransicionPeer::ORDEN, WfActividadTransicionPeer::TABLE_NAME,WfActividadTransicionPeer::WF_FLUJO_ID);
    $sentencia = $conexion->prepare($consulta);
    $sentencia->execute();
    $resultset = $sentencia->fetch(PDO::FETCH_OBJ);
    return ($resultset->max + 1);    
  }


