  public function executeDeleteGrant()
  {
    $wat_id = $this->getRequestParameter('wfactividadtransicion_id');
    $enviar_alertas = $this->getRequestParameter('enviar_alertas');      
  	$this->wf_actividad_transicion = WfActividadTransicionPeer::retrieveByPk($wat_id);
  	//************************************************************************************************
  	//$select_usuarios = $this->getRequestParameter('usuario_id');
    $select_usuarios = preg_split("/[,]+/",$this->getRequestParameter('WfusuarioId'), null, PREG_SPLIT_NO_EMPTY);
    $user_active = $this->deleteUsuarios($wat_id,$select_usuarios);
    //************************************************************************************************
  	if(count($select_usuarios) > 0){
	    if($wat_id > 0){
            //****************************************************************************************
            foreach ($select_usuarios as $item){
                if(!in_array($item,$user_active)){
                    $objGrant= new WfActividadtransicionUsuario();
                    $objGrant->setWfactividadtransicionId($wat_id);
                    $objGrant->setUsuarioId($item);
                    $objGrant->setEnviarAlerta(trim($enviar_alertas) ? 1 : 0);
                    $objGrant->save();
                }
            }
            //****************************************************************************************
		}
	}
    //************************************************************************************************
    return $this->redirect($this->getRequest()->getScriptName().'/wf_detalles/grant?wf_actividad_transicion_id=' . $wat_id );    
  }
  
