    if( is_numeric($wftransicion_id) &&  is_numeric($wfactividad_id)){
        $c = new Criteria();
        $c->add(WfPermisoTransicionActividadPeer::WF_TRANSICION_ID,$wftransicion_id);
        $c->add(WfPermisoTransicionActividadPeer::WF_ACTIVIDAD_ID,$wfactividad_id);
        $result = WfPermisoTransicionActividadPeer::doCount($c);
        if(!$result){
            $object = new WfPermisoTransicionActividad();
            $object->setWfActividadId($wfactividad_id);
            $object->setWfTransicionId($wftransicion_id);
            $object->save();
        }
    }
  }
  
