  public function executeDeleteVariableWf()
  {
    if ($this->getRequestParameter('wfvariable_id'))
    {
      $wf_variable = WfVariablePeer::retrieveByPk($this->getRequestParameter('wfvariable_id'));
      $wf_actividad_transicion = WfActividadTransicionPeer::retrieveByPK($wf_variable->getWfactividadtransicionId());
