  public function executeSaveOrDeleteVarsWf()
  {
    if (!$this->getRequestParameter('wfvariable_id'))
    {
      $wf_variable = new WfVariable();
    }
    else
    {
      $wf_variable = WfVariablePeer::retrieveByPk($this->getRequestParameter('wfvariable_id'));
      $this->forward404Unless($wf_variable);
    }
    $wf_actividad_transicion = WfActividadTransicionPeer::retrieveByPK($this->getRequestParameter('wfactividadtransicion_id'));
    //***********************************************************************************************************
    $wf_variable->setWfactividadtransicionId($wf_actividad_transicion->getPrimaryKey());
    $wf_variable->setNombre($this->getRequestParameter('nombre'));
    $wf_variable->setWftipodatoId($this->getRequestParameter('wftipodato_id'));
    $wf_variable->setOrden($this->getRequestParameter('orden'));
    $wf_variable->save();
    //***********************************************************************************************************
    $this->wf_actividad_transicion = $wf_actividad_transicion;
    $this->listVarsActByTransicion = WfVariablePeer::getAllWfVariablesByActTransicion($wf_actividad_transicion->getPrimaryKey());    
  }
  
  public function executeSaveOrDeleteUserWf()
  {
    $wat_id = $this->getRequestParameter('wfactividadtransicion_id');
    $enviar_alertas = $this->getRequestParameter('enviar_alertas');      
  	$this->wf_actividad_transicion = WfActividadTransicionPeer::retrieveByPk($wat_id);
  	//************************************************************************************************
  	//$select_usuarios = $this->getRequestParameter('usuario_id');
    $select_usuarios = preg_split("/[,]+/",$this->getRequestParameter('WfusuarioId'), null, PREG_SPLIT_NO_EMPTY);
    $user_active = $this->deleteUsuarios($wat_id,$select_usuarios);
    //************************************************************************************************
  	if(count($select_usuarios) > 0){
	    if($wat_id > 0){
            foreach ($select_usuarios as $item){
                if(!in_array($item,$user_active)){
                    $objGrant= new WfActividadtransicionUsuario();
                    $objGrant->setWfactividadtransicionId($wat_id);
                    $objGrant->setUsuarioId($item);
                    $objGrant->setEnviarAlerta(trim($enviar_alertas) ? 1 : 0);
                    $objGrant->save();
                }
            }
		}
	}
    //************************************************************************************************
    if( $wat_id > 0 ){ $this->getUserByActividadTranscicion($wat_id); }
  }
  
