  public function getUserByActividadTranscicion($myid)
  {    
    $this->users_id = array();
    $this->users_cuid = array();
    $this->users_text = array();
    //***********************************************************************************************
  	if( $myid > 0 ){
    	$c = new Criteria();
      	$c->add(WfActividadtransicionUsuarioPeer::WFACTIVIDADTRANSICION_ID, $myid);
      	$wf_actividadtransicion_usuarios = WfActividadTransicionUsuarioPeer::doSelect($c);
        //*******************************************************************************************
        foreach ($wf_actividadtransicion_usuarios as $row){
            $this->users_id[] = $row->getUsuario()->getUsuarioId();
            $this->users_text[] = ($row->getUsuario()->getNombreAll());
        }
        //*******************************************************************************************
        $this->wf_actividadtransicion_usuarios = $wf_actividadtransicion_usuarios;
	}
  }
  
