  public function deleteUsuarios($wat_id, $users = array()){
    $users_active = array();
    $wat_active = array();
	//echo "aqui wat_id".$wat_id;exit;
    if(trim($wat_id)){        
        foreach($users as $urow){
            $datal = $this->IsUserAdded($wat_id, $urow);
            if(count($datal)){            
                $wat_active[] = $datal[0];
                $users_active[] = $datal[1];
            }
        }
        //*******************************************************************
        if(count($wat_active)){                
            $consulta = "DELETE FROM %s WHERE %s NOT IN(".implode(",",$wat_active).") AND %s = ".$wat_id.";";
            $consulta = sprintf($consulta,WfActividadtransicionUsuarioPeer::TABLE_NAME,WfActividadtransicionUsuarioPeer::WFACTIVIDADTRANSICIONUSUARIO_ID,WfActividadtransicionUsuarioPeer::WFACTIVIDADTRANSICION_ID);
        }else{
            $consulta = "DELETE FROM %s WHERE %s = ".$wat_id.";";
            $consulta = sprintf($consulta,WfActividadtransicionUsuarioPeer::TABLE_NAME,WfActividadtransicionUsuarioPeer::WFACTIVIDADTRANSICION_ID);            
        }
        $conexion = Propel::getConnection();
        $sentencia = $conexion->prepare($consulta);
        $sentencia->execute();
        //*******************************************************************
    }
    return $users_active;
  }
  
  public function DeleteAllUsuarios($wf_actividad_transicion_id)
  {
	if($wf_actividad_transicion_id){
		$conexion = Propel::getConnection();
		$consulta = "DELETE FROM %s WHERE %s =".$wf_actividad_transicion_id;
		$consulta = sprintf($consulta,WfActividadtransicionUsuarioPeer::TABLE_NAME,WfActividadtransicionUsuarioPeer::WFACTIVIDADTRANSICION_ID);
		$sentencia = $conexion->prepare($consulta);
		$sentencia->execute();            
	}
  }
  
  public function deleteAllPermActByTransicion($wfactividad_id, $wftransicion_id)
  {
	if( is_numeric($wfactividad_id) &&  is_numeric($wftransicion_id)){
		$conexion = Propel::getConnection();
		$query = "DELETE FROM %s WHERE %s = $wfactividad_id AND %s = $wftransicion_id";
		$query = sprintf($query,WfPermisoTransicionActividadPeer::TABLE_NAME,WfPermisoTransicionActividadPeer::WF_ACTIVIDAD_ID,WfPermisoTransicionActividadPeer::WF_TRANSICION_ID);
		$sentencia = $conexion->prepare($query);
		$sentencia->execute();             
	}
  }
  
  public function IsUserAdded($wat_id, $usuario_id)
  {
    $data = array();
    if($usuario_id <= 0 && $wat_id <= 0){
        return null;
    }
    //*********************************************************************************    
    $c4 = new Criteria();
	$c4->add(WfActividadtransicionUsuarioPeer::WFACTIVIDADTRANSICION_ID, $wat_id);
	$c4->add(WfActividadtransicionUsuarioPeer::USUARIO_ID,$usuario_id);
	$rs = WfActividadtransicionUsuarioPeer::doSelect($c4);
    //*********************************************************************************
    foreach($rs as $row){
        $data[] = $row->getPrimaryKey();
        $data[] = $row->getUsuarioId();
    }
    //*********************************************************************************
    return $data;
  }
  
  public function executeRevoke()
  {
  	$wat_id=$this->getRequestParameter('wf_actividad_transicion_id');
  	$this->wf_actividad_transicion = WfActividadTransicionPeer::retrieveByPk($wat_id);
  	
  	$usuario_id=$this->getRequestParameter('usuario_id');
  	if($usuario_id>0){
	    if($wat_id>0){
		$c4=new Criteria();
		$c4->add(WfActividadtransicionUsuarioPeer::WFACTIVIDADTRANSICION_ID, $wat_id);
		$c4->add(WfActividadtransicionUsuarioPeer::USUARIO_ID,$usuario_id);
		$rs=WfActividadtransicionUsuarioPeer::doSelect($c4);
		$cantidad = 0;
		foreach($rs as $row){
			$cantidad++;
			$watu_id=$row->getWfactividadtransicionusuarioId();
			$objGrant = WfActividadTransicionUsuarioPeer::retrieveByPk($watu_id);
			$objGrant->delete();	
		}	
		}
	}
    if( $wat_id>0 ){
	$myid=$wat_id;	
	$c=new Criteria();
  	$c->add(WfActividadtransicionUsuarioPeer::WFACTIVIDADTRANSICION_ID, $myid);
  	$this->wf_actividadtransicion_usuarios=WfActividadTransicionUsuarioPeer::doSelect($c);
	  
	$c2=new Criteria();
	$c2->add(UsuarioPeer::ESTADOUSUARIO_ID,1);
	$this->arreglo_usuarios=UsuarioPeer::doSelect($c2);  
	}
    return $this->redirect($this->getRequest()->getScriptName().'/wf_detalles/grant?wf_actividad_transicion_id=' . $wat_id );
  }





